        dt = datetime.datetime.fromtimestamp(ts/1000)
        # Get message content
        msg = d.get('message', d.get('content',''))
        if isinstance(msg, list):
            for m in msg:
                if isinstance(m, dict) and m.get('type') == 'text':
                    content = m.get('text','')[:100]
                elif isinstance(m, dict) and m.get('type') == 'thinking':
                    content = '[thinking] ' + m.get('thinking','')[:80]
                else:
                    content = str(m)[:100]
                print(f'{dt.strftime(\"%H:%M:%S\")} [{role}] {content}')
        else:
            print(f'{dt.strftime(\"%H:%M:%S\")} [{role}] {str(msg)[:100]}')
    except Exception as e:
        pass
