import sys, json
lines = sys.stdin.read().strip().split('\n')
print(f'Total tail lines: {len(lines)}')
for line in lines[-8:]:
    try:
        d = json.loads(line)
        ts = d.get('timestamp', d.get('time', 0))
        import datetime
        try:
            dt = datetime.datetime.fromtimestamp(float(ts)/1000)
            ts_str = dt.strftime('%H:%M:%S')
        except:
            ts_str = str(ts)[:19]
        role = d.get('role', d.get('message', {}).get('role', 'unknown'))
        # Get content summary
        content = d.get('content', d.get('message', {}).get('content', ''))
        if isinstance(content, list):
            texts = []
            for c in content:
                if isinstance(c, dict):
                    if c.get('type') == 'text':
                        texts.append(c.get('text', '')[:80])
                    elif c.get('type') == 'thinking':
                        texts.append('[thinking] ' + c.get('thinking', '')[:60])
            content = ' | '.join(texts)
        elif isinstance(content, dict):
            content = str(content.get('text', content))[:80]
        print(f'{ts_str} [{role}] {str(content)[:100]}')
    except Exception as e:
        print(f'Parse error: {e}')
" 2>/dev/null

